INSERT INTO `categories` VALUES (14,'Smart Security','Smart Security Product in Bangladesh- Stata IT Limited','Discover top-notch smart security products in Bangladesh for high protection. Our smart product features like real-time video monitoring, motion detection, and remote access','2022-09-10 07:18:07','2023-07-12 08:23:57',NULL),(15,'Switch and Sockets','Smart Switch and Socket Price in Bangladesh- Stata It Limited','Modernize your home with Wi-Fi smart switch and sockets. Effortlessly control your devices, schedule operations, and manage energy consumption. Discover the perfect solution for your needs.','2022-09-12 09:14:58','2023-07-24 07:18:54',NULL),(16,'Smart Door Locks','Smart door lock in Bangladesh- Stata It Limited','Secure your home with a smart door lock in Bangladesh. Keyless entry with advanced security features. Find the perfect smart door lock for your home today','2022-09-18 11:09:59','2023-07-12 08:50:24',NULL),(17,'Smart Home Appliances','Smart Home Appliance in Bangladesh- Stata It Limited','Transform your home with smart home appliances in Bangladesh. Experience and Explore a range of intelligent appliances for an upgraded living experience','2022-09-20 05:04:14','2023-07-12 09:52:46',NULL),(18,'Smart Lighting','Smart Wi-Fi light in Bangladesh- Stata It Limited','Upgrade your home with smart Wi-Fi lights. Enjoy customizable settings, voice control, and energy efficiency. Discover the perfect smart lighting solution for your space','2022-09-21 09:58:03','2023-07-12 10:18:35',NULL),(19,'Smart Home Package','Upgrade Your Lifestyle with a Smart Home Package- Stata IT','Our smart home package offers a range of features tailored to suit your needs. Buy now Stata Smart product and embrace the future of living.','2023-04-02 18:45:04','2023-07-13 06:12:45',NULL),(21,'Smart Hotel Solution','Smart Hotel Solution in Bangladesh-Stata IT Limited','Looking for the best Smart Hotel Solution in Bangladesh? Look no further! we offer customized solutions to enhance guest experiences and streamline operations. Discover the future of hospitality with our cutting-edge technology and personalized approach.','2023-05-28 16:34:33','2023-07-12 09:59:41',NULL),(24,'Touch Switch','Premium Touch Switch Price in Bangladesh- Stata IT Limited','Buy now and transform your living space with our Touch switches. Control your lights with a simple touch and add a touch of modern elegance.','2023-07-12 17:55:51','2023-08-28 10:15:31',NULL);
